        raise ValueError("xs must have an even number of coefficients")
    if xs[-1] == 0:
        raise ValueError("Largest coefficient cannot be zero")
    a, b = -1, 1
    while poly(xs, b) * poly(xs, a) > 0:
        a, b = b, b * 2
    while b - a > 1e-5:
        c = (a + b) / 2
        if poly(xs, c) * poly(xs, a) < 0:
            b = c
        else:
            a = c
    return (a + b) / 2
